'use strict';
// Tiny zero-dependency bundler for the SEA build.
// Wraps server.js and every lib/*.js file into one CommonJS script with a module registry:
//   function (module, exports, require, __filename, __dirname) { ...source... }
// Relative requires ('./x', '../x') are resolved through the registry at build time; built-in
// modules ('fs', 'node:sea', ...) are passed through to the real require.
// Usage: node build/bundle.js   ->  dist/bundle.cjs

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'dist');
const OUT_FILE = path.join(OUT_DIR, 'bundle.cjs');
const ENTRY = 'server.js';
const REQUIRE_RE = /\brequire\(\s*(['"])([^'"]+)\1\s*\)/g;

const toAbs = (id) => path.join(ROOT, ...id.split('/'));
const isRelative = (spec) => spec.startsWith('./') || spec.startsWith('../') || spec === '.' || spec === '..';

// Resolve a relative spec from a module id (project-relative, forward slashes) to a module id.
function resolveId(fromId, spec) {
  const target = path.posix.normalize(path.posix.join(path.posix.dirname(fromId), spec));
  for (const c of [target, target + '.js', target + '/index.js']) {
    const abs = toAbs(c);
    if (fs.existsSync(abs) && fs.statSync(abs).isFile()) return c;
  }
  throw new Error(`bundle: cannot resolve "${spec}" required from ${fromId}`);
}

// Relative requires of one module -> { spec: resolvedId }.
function relativeDeps(id, src) {
  const deps = {};
  REQUIRE_RE.lastIndex = 0;
  let m;
  while ((m = REQUIRE_RE.exec(src))) {
    if (isRelative(m[2])) deps[m[2]] = resolveId(id, m[2]);
  }
  return deps;
}

// Collect every module reachable from the entry, plus all lib/*.js (the registry always
// carries the full lib/ set, as the build contract requires).
const sources = new Map(); // id -> source text
const deps = new Map();    // id -> { spec: id }
const queue = [ENTRY];
for (const f of fs.readdirSync(path.join(ROOT, 'lib')).sort()) {
  if (f.endsWith('.js')) queue.push('lib/' + f);
}
while (queue.length) {
  const id = queue.shift();
  if (sources.has(id)) continue;
  const src = fs.readFileSync(toAbs(id), 'utf8');
  sources.set(id, src);
  const d = relativeDeps(id, src);
  deps.set(id, d);
  for (const dep of Object.values(d)) queue.push(dep);
}

const out = [];
out.push("'use strict';");
out.push('// Generated by build/bundle.js. Do not edit by hand.');
out.push('(function () {');
out.push('  const __nodeRequire = require;');

// Module bodies. The source is embedded verbatim inside a function, so each module keeps its
// own 'use strict' directive and its own scope.
out.push('  const __defs = {');
for (const [id, src] of sources) {
  out.push(`    ${JSON.stringify(id)}: function (module, exports, require, __filename, __dirname) {`);
  out.push(`// ---- ${id} ----`);
  out.push(src);
  out.push('\n    },');
}
out.push('  };');

// Per-module metadata: real absolute file/dir (for __filename/__dirname) and relative-require map.
out.push('  const __meta = {');
for (const id of sources.keys()) {
  out.push(`    ${JSON.stringify(id)}: { file: ${JSON.stringify(toAbs(id))}, dir: ${JSON.stringify(path.dirname(toAbs(id)))}, deps: ${JSON.stringify(deps.get(id))} },`);
}
out.push('  };');

out.push('  const __cache = Object.create(null);');
out.push('  function load(id) {');
out.push('    if (__cache[id]) return __cache[id].exports;');
out.push('    const mod = { exports: {} };');
out.push('    __cache[id] = mod;');
out.push('    const meta = __meta[id];');
out.push('    const localRequire = function (spec) {');
out.push('      if (Object.prototype.hasOwnProperty.call(meta.deps, spec)) return load(meta.deps[spec]);');
out.push('      return __nodeRequire(spec);');
out.push('    };');
out.push('    __defs[id].call(mod.exports, mod, mod.exports, localRequire, meta.file, meta.dir);');
out.push('    return mod.exports;');
out.push('  }');
out.push(`  load(${JSON.stringify(ENTRY)});`);
out.push('})();');
out.push('');

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(OUT_FILE, out.join('\n'), 'utf8');
console.log(`bundle: ${sources.size} modules -> ${path.relative(ROOT, OUT_FILE)} (${fs.statSync(OUT_FILE).size} bytes)`);
for (const id of sources.keys()) console.log('  ' + id);
